package com.portfolio.features.experience.entity;
import com.portfolio.features.portfolio.entity.Portfolio; import jakarta.persistence.*; import java.time.*; import java.util.*; import lombok.*;
@Entity @Table(name="experiences") @Getter @Setter @NoArgsConstructor public class Experience { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="portfolio_id") private Portfolio portfolio; @Column(nullable=false) private String company; @Column(nullable=false) private String position; private String location; private LocalDate startDate; private LocalDate endDate; private boolean currentlyWorking; @Column(columnDefinition="TEXT") private String description; private int sortOrder; private LocalDateTime createdAt, updatedAt; @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();}@PreUpdate void update(){updatedAt=LocalDateTime.now();} }
